// WHY: Keeps the selected declaration through a normal read of a generated ZIP entry.

package io.github.spockz.example.forbidden;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;

/** Reads a known, well-formed ZIP through the generic InputStream API. */
public final class StreamApplication {
  private StreamApplication() {}

  /** Reads only data generated by this fixture. */
  public static void main(final String[] args) throws IOException {
    final ByteArrayOutputStream archive = new ByteArrayOutputStream();
    try (ZipOutputStream output = new ZipOutputStream(archive)) {
      output.putNextEntry(ArchiveExample.entry());
      output.write("hello".getBytes(StandardCharsets.US_ASCII));
      output.closeEntry();
    }
    try (ZipArchiveInputStream zip =
        new ZipArchiveInputStream(new ByteArrayInputStream(archive.toByteArray()))) {
      final String name = zip.getNextZipEntry().getName();
      final InputStream input = zip;
      final byte[] contents = new byte[5];
      final int count = input.read(contents, 0, contents.length);
      if (count != contents.length) {
        throw new IOException("Expected a complete fixture entry");
      }
      System.out.println(name + ": " + new String(contents, StandardCharsets.US_ASCII));
    }
  }
}
